CREATE TABLE IF NOT EXISTS institutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh');
CREATE TABLE IF NOT EXISTS faculties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutions, name text NOT NULL, external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), faculty_id uuid NOT NULL REFERENCES faculties, name text NOT NULL, external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), faculty_id uuid NOT NULL REFERENCES faculties, name text NOT NULL, external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS terms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutions, name text NOT NULL, academic_year text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutions, name text NOT NULL, email text UNIQUE NOT NULL, student_code text, microsoft_id text UNIQUE, external_id text UNIQUE, faculty_id uuid REFERENCES faculties, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id text PRIMARY KEY, name text NOT NULL, permissions jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS user_roles(user_id uuid NOT NULL REFERENCES users, role_id text NOT NULL REFERENCES roles, PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, device text NOT NULL, token_cache text);
CREATE TABLE IF NOT EXISTS auth_states(id text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutions, faculty_id uuid REFERENCES faculties, code text NOT NULL UNIQUE, name text NOT NULL, credits integer NOT NULL DEFAULT 3, description text NOT NULL DEFAULT '', image text, external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS course_offerings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES courses, term_id uuid NOT NULL REFERENCES terms, external_id text UNIQUE, UNIQUE(course_id,term_id));
CREATE TABLE IF NOT EXISTS sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offering_id uuid NOT NULL REFERENCES course_offerings, name text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','READ_ONLY','ARCHIVED')), external_id text UNIQUE);
CREATE TABLE IF NOT EXISTS enrollments(section_id uuid NOT NULL REFERENCES sections, user_id uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('STUDENT','LECTURER','ASSISTANT','GRADER','AUDITOR')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(section_id,user_id));
CREATE TABLE IF NOT EXISTS modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, position integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS module_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES modules, title text NOT NULL, type text NOT NULL DEFAULT 'PAGE', content text NOT NULL DEFAULT '', url text, position integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'DRAFT', available_at timestamptz, prerequisite_id uuid REFERENCES module_items, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS item_progress(user_id uuid NOT NULL REFERENCES users, item_id uuid NOT NULL REFERENCES module_items, completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS rubrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, criteria jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, description text NOT NULL DEFAULT '', due_at timestamptz NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), closes_at timestamptz, points numeric NOT NULL DEFAULT 10 CHECK(points>0), max_attempts integer NOT NULL DEFAULT 3 CHECK(max_attempts>0), late_allowed boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'DRAFT', rubric_id uuid REFERENCES rubrics, category text NOT NULL DEFAULT 'Assignments', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS file_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, owner_id uuid NOT NULL REFERENCES users, name text NOT NULL, mime text NOT NULL, size integer NOT NULL, storage_key text NOT NULL UNIQUE, checksum text NOT NULL, status text NOT NULL DEFAULT 'READY', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments, user_id uuid NOT NULL REFERENCES users, attempt integer NOT NULL, text text NOT NULL DEFAULT '', url text, files jsonb NOT NULL DEFAULT '[]', status text NOT NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,user_id,attempt), UNIQUE(assignment_id,user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS question_banks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL);
CREATE TABLE IF NOT EXISTS questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bank_id uuid NOT NULL REFERENCES question_banks, type text NOT NULL, prompt text NOT NULL, options jsonb NOT NULL DEFAULT '[]', answer jsonb NOT NULL, points numeric NOT NULL DEFAULT 1 CHECK(points>0), explanation text NOT NULL DEFAULT '', tags jsonb NOT NULL DEFAULT '[]', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quizzes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, description text NOT NULL DEFAULT '', duration_minutes integer NOT NULL DEFAULT 15 CHECK(duration_minutes>0), opens_at timestamptz NOT NULL DEFAULT now(), closes_at timestamptz NOT NULL, max_attempts integer NOT NULL DEFAULT 2 CHECK(max_attempts>0), shuffle boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'DRAFT', review_policy text NOT NULL DEFAULT 'AFTER_CLOSE', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS quiz_questions(quiz_id uuid NOT NULL REFERENCES quizzes, question_id uuid NOT NULL REFERENCES questions, position integer NOT NULL DEFAULT 0, PRIMARY KEY(quiz_id,question_id));
CREATE TABLE IF NOT EXISTS quiz_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id uuid NOT NULL REFERENCES quizzes, user_id uuid NOT NULL REFERENCES users, attempt integer NOT NULL, questions jsonb NOT NULL, answers jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, submitted_at timestamptz, score numeric, max_score numeric, status text NOT NULL DEFAULT 'IN_PROGRESS', device text, UNIQUE(quiz_id,user_id,attempt));
CREATE TABLE IF NOT EXISTS grade_categories(section_id uuid NOT NULL REFERENCES sections, name text NOT NULL, weight numeric NOT NULL CHECK(weight>=0 AND weight<=100), PRIMARY KEY(section_id,name));
CREATE TABLE IF NOT EXISTS grades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, user_id uuid NOT NULL REFERENCES users, source_type text NOT NULL, source_id uuid NOT NULL, title text NOT NULL, category text NOT NULL, score numeric NOT NULL CHECK(score>=0), max_score numeric NOT NULL CHECK(max_score>0), feedback text NOT NULL DEFAULT '', rubric_scores jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'DRAFT', graded_by uuid REFERENCES users, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,source_type,source_id), CHECK(score<=max_score));
CREATE TABLE IF NOT EXISTS announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, content text NOT NULL, pinned boolean NOT NULL DEFAULT false, publish_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, author_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS discussions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, author_id uuid NOT NULL REFERENCES users, locked boolean NOT NULL DEFAULT false, pinned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS discussion_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discussion_id uuid NOT NULL REFERENCES discussions, author_id uuid NOT NULL REFERENCES users, parent_id uuid REFERENCES discussion_posts, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS study_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, name text NOT NULL, description text NOT NULL DEFAULT '', leader_id uuid REFERENCES users);
CREATE TABLE IF NOT EXISTS group_members(group_id uuid NOT NULL REFERENCES study_groups, user_id uuid NOT NULL REFERENCES users, PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS calendar_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid REFERENCES sections, owner_id uuid REFERENCES users, title text NOT NULL, kind text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, location text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS teams_meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL UNIQUE REFERENCES calendar_events, organizer_id uuid NOT NULL REFERENCES users, microsoft_event_id text UNIQUE, join_url text, sync_status text NOT NULL DEFAULT 'PENDING', error text, idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, code_hash text NOT NULL, created_by uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'OPEN');
CREATE TABLE IF NOT EXISTS attendance_records(session_id uuid NOT NULL REFERENCES attendance_sessions, user_id uuid NOT NULL REFERENCES users, status text NOT NULL CHECK(status IN ('PRESENT','LATE','ABSENT','EXCUSED')), recorded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, title text NOT NULL, content text NOT NULL, href text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_preferences(user_id uuid PRIMARY KEY REFERENCES users, preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES users, recipient_id uuid NOT NULL REFERENCES users, content text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learning_outcomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, code text NOT NULL, description text NOT NULL, plo text NOT NULL DEFAULT '', threshold numeric NOT NULL DEFAULT 50);
CREATE TABLE IF NOT EXISTS outcome_mappings(outcome_id uuid NOT NULL REFERENCES learning_outcomes, assignment_id uuid NOT NULL REFERENCES assignments, weight numeric NOT NULL CHECK(weight>0 AND weight<=100), PRIMARY KEY(outcome_id,assignment_id));
CREATE TABLE IF NOT EXISTS support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, title text NOT NULL, content text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sis_sync_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES users, payload jsonb NOT NULL, summary jsonb NOT NULL, status text NOT NULL DEFAULT 'PREVIEW', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users, action text NOT NULL, resource text NOT NULL, resource_id text, old_value jsonb, new_value jsonb, ip text, user_agent text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_enrollments_user ON enrollments(user_id,active);
CREATE INDEX IF NOT EXISTS idx_modules_section ON modules(section_id,position);
CREATE INDEX IF NOT EXISTS idx_submissions_assignment ON submissions(assignment_id,user_id,attempt);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_discussion ON discussion_posts(discussion_id,created_at);
CREATE INDEX IF NOT EXISTS idx_grades_user ON grades(user_id,section_id,status);
ALTER TABLE quiz_attempts ADD COLUMN IF NOT EXISTS manual_scores jsonb NOT NULL DEFAULT '{}';
ALTER TABLE quiz_attempts ADD COLUMN IF NOT EXISTS review_feedback text NOT NULL DEFAULT '';
ALTER TABLE announcements ADD COLUMN IF NOT EXISTS notified_at timestamptz;
ALTER TABLE module_items ADD COLUMN IF NOT EXISTS content_format text NOT NULL DEFAULT 'TEXT';
ALTER TABLE module_items ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS item_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES module_items, revision integer NOT NULL, snapshot jsonb NOT NULL, created_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(item_id,revision));
ALTER TABLE file_assets ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PRIVATE','COURSE','GROUP'));
ALTER TABLE file_assets ADD COLUMN IF NOT EXISTS group_id uuid REFERENCES study_groups;
CREATE TABLE IF NOT EXISTS group_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES study_groups, author_id uuid NOT NULL REFERENCES users, content text NOT NULL, file_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES support_tickets, author_id uuid NOT NULL REFERENCES users, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE support_tickets ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE INDEX IF NOT EXISTS idx_group_posts ON group_posts(group_id,created_at);
CREATE TABLE IF NOT EXISTS learning_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), section_id uuid NOT NULL REFERENCES sections, actor_id uuid NOT NULL REFERENCES users, payload jsonb NOT NULL, summary jsonb NOT NULL, status text NOT NULL DEFAULT 'PREVIEW', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
